import{_ as t,a,c as i,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"程序员英语 06：代码评审与技术说明","description":"用条件、后果与理由写清评审意见，并把复杂技术方案整理成读者能采取行动的说明。","frontmatter":{"title":"程序员英语 06：代码评审与技术说明","description":"用条件、后果与理由写清评审意见，并把复杂技术方案整理成读者能采取行动的说明。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"程序员英语","summary":"用条件、后果与理由写清评审意见，并把复杂技术方案整理成读者能采取行动的说明。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr"},"next":{"text":"程序员英语 07：会议、听力与技术表达","link":"/life/english/programmer/listening-speaking"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr"},"next":{"text":"程序员英语 07：会议、听力与技术表达","link":"/life/english/programmer/listening-speaking"}},"headers":[],"relativePath":"life/english/programmer/review-writing.md","filePath":"life/english/programmer/review-writing.md"}'),r={name:"life/english/programmer/review-writing.md"};function o(s,e,l,d,c,p){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="程序员英语-06-代码评审与技术说明" tabindex="-1">程序员英语 06：代码评审与技术说明 <a class="header-anchor" href="#程序员英语-06-代码评审与技术说明" aria-label="Permalink to &quot;程序员英语 06：代码评审与技术说明&quot;">​</a></h1><p>一句 <code>This is wrong.</code> 表达了否定，却没有让作者知道哪里错、何时错、应该检查什么。技术协作中的英语应把判断转化为可讨论的证据。</p><h2 id="评审意见的三部分" tabindex="-1">评审意见的三部分 <a class="header-anchor" href="#评审意见的三部分" aria-label="Permalink to &quot;评审意见的三部分&quot;">​</a></h2><p>假设代码取列表的第一个元素，没有检查空列表。可以写：</p><blockquote><p>If the input list is empty, this access fails before validation runs. Could we check the length first and add an empty-input case?</p></blockquote><p>第一部分是触发条件，第二部分是后果，第三部分是建议与验证。评论指向代码行为，无需评价作者能力。</p><p><a href="https://google.github.io/eng-practices/review/reviewer/comments.html" target="_blank" rel="noopener noreferrer">Google 代码评审指南</a> 强调礼貌、解释理由和关注代码。落到日常写作，可以给不同性质的意见加上明确提示：</p><table tabindex="0"><thead><tr><th>性质</th><th>示例</th></tr></thead><tbody><tr><td>阻止合并的问题</td><td>Blocking: This can discard unsaved edits when the user cancels.</td></tr><tr><td>需要澄清</td><td>Question: Is the input guaranteed to be sorted here?</td></tr><tr><td>改进建议</td><td>Suggestion: Naming this value <code>timeoutMs</code> would make the unit clearer.</td></tr><tr><td>轻微风格意见</td><td>Nit: Consider using the existing term “record” for consistency.</td></tr></tbody></table><p>这些标签是表达方法，不是通用强制标准。团队有约定时按约定使用；不能把数据丢失问题写成 <code>Nit</code> 来弱化风险。</p><h2 id="回复时说明处理结果" tabindex="-1">回复时说明处理结果 <a class="header-anchor" href="#回复时说明处理结果" aria-label="Permalink to &quot;回复时说明处理结果&quot;">​</a></h2><p>仅回 <code>Done</code>，评审者仍要重新查找修改。更具体的回复是：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Added the empty-input check before indexing the list.</span></span>
<span class="line"><span>The new test covers an empty list and confirms that validation returns an error.</span></span></code></pre></div><p>不同意建议时也先说明约束：<code>Sorting here would change the output order required by the file format. Could we keep the original order and validate it instead?</code> 这比 <code>I don&#39;t agree</code> 多提供了一个可核对的理由。所说的格式要求必须确有依据。</p><h2 id="技术说明-先写读者需要的结论" tabindex="-1">技术说明：先写读者需要的结论 <a class="header-anchor" href="#技术说明-先写读者需要的结论" aria-label="Permalink to &quot;技术说明：先写读者需要的结论&quot;">​</a></h2><p>想解释一个导出流程，不必从内部类名讲起。可以按“行为、原因、边界、验证”组织：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>The exporter writes to a temporary file before replacing the target.</span></span>
<span class="line"><span>This keeps an incomplete export from being mistaken for a finished report.</span></span>
<span class="line"><span>We still need to verify the replacement behavior on each supported platform.</span></span>
<span class="line"><span>The current test covers an interrupted write before the replacement step.</span></span></code></pre></div><p>说明把已知结果与未验证边界分开。不要据此声称任何平台、任何文件系统上替换都具备相同保证。</p><p>删除空泛的引导语也能让句子更清晰：把 <code>It is important to note that the cache is cleared when the file changes.</code> 简化成 <code>The cache is cleared when the file changes.</code>。主语明确时也可写 <code>The watcher clears the cache when the file changes.</code>；不知道执行者时，保留被动语态比编造主语准确。</p><h2 id="练习-修改评审语气与信息量" tabindex="-1">练习：修改评审语气与信息量 <a class="header-anchor" href="#练习-修改评审语气与信息量" aria-label="Permalink to &quot;练习：修改评审语气与信息量&quot;">​</a></h2><p>原意见：<code>Why didn&#39;t you think about concurrency? This is bad.</code></p><p>已知：两个线程可能同时读到计数 9，再各自写入 10，预期最终应为 11。写一条可操作的英文评审意见。再把 <code>It is very obvious that this implementation is much better.</code> 改成一个需要证据的具体说明。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p>评审意见：<code>If two threads read the same counter value, one update can overwrite the other. Could we protect the read-modify-write operation and add a concurrent-update test?</code></p><p>技术说明可以写：<code>This implementation performs one file scan instead of two. We still need a benchmark to compare the total runtime.</code></p><p>第二句是一个写法示例，只有实际从两次扫描变成一次时才能使用。删除 <code>obvious</code> 和 <code>better</code>，用可核对的变化替代；运行次数减少也不直接等于总耗时减半。</p></details><h2 id="资料与延伸" tabindex="-1">资料与延伸 <a class="header-anchor" href="#资料与延伸" aria-label="Permalink to &quot;资料与延伸&quot;">​</a></h2><p><a href="https://developers.google.com/style/tone" target="_blank" rel="noopener noreferrer">Google 文档语气指南</a> 可作为改稿参考。练习时读出自己的评论，检查是否缺少条件、是否把猜测写成事实、是否让对方知道下一步。</p>`,24)])])}const g=t(r,[["render",o]]);export{u as __pageData,g as default};
